package io.dndroll.backup;
import static org.junit.jupiter.api.Assertions.*;
import java.util.*;
import org.junit.jupiter.api.Test;
class CampaignRemapPlanTest {
    final UUID source=UUID.randomUUID(),target=UUID.randomUUID(),seed=UUID.randomUUID(),shared=UUID.randomUUID();final String digest="a".repeat(64);
    List<CampaignRemapPlan.Table> tables(){return tables(ids());}
    List<CampaignRemapPlan.Table> tables(List<CampaignRemapPlan.Identity> identities){return RecoveryInventory.catalog().keySet().stream().map(n->new CampaignRemapPlan.Table(n,CampaignRemapPlan.scope(n),identities.stream().filter(i->i.namespace().equals(n)).count(),CampaignRemapPlan.columns(n))).toList();}
    CampaignRemapPlan.Report plan(List<CampaignRemapPlan.Identity> ids,List<CampaignRemapPlan.Reference> refs,Set<UUID> occupied,List<CampaignRemapPlan.Table> tables){return CampaignRemapPlan.plan(source,target,seed,digest,ids,refs,occupied,tables);}
    List<CampaignRemapPlan.Identity> ids(){return List.of(new CampaignRemapPlan.Identity("campaign",source,3L),new CampaignRemapPlan.Identity("character_card",shared,9L),new CampaignRemapPlan.Identity("dice_roll",shared,2L));}
    @Test void proposesDistinctNamespacedIdsWithoutResettingVersionsOrClaimsOfExecution(){var p=plan(ids(),List.of(),Set.of(source,shared),tables());assertEquals("BLOCKED",p.status());assertFalse(p.executable());assertEquals(3,p.mappings().size());assertEquals(3,p.mappings().stream().map(CampaignRemapPlan.Mapping::target).distinct().count());assertTrue(p.mappings().stream().anyMatch(m->m.namespace().equals("campaign")&&m.target().equals(target)&&m.version()==3L));assertTrue(p.mappings().stream().anyMatch(m->m.namespace().equals("character_card")&&m.version()==9L));assertEquals(Set.of("REMAP_WRITER_NOT_IMPLEMENTED","TARGET_AUTHORITY_REVIEW_REQUIRED","HASH_REBIND_NOT_IMPLEMENTED","TYPED_JSON_REBIND_NOT_IMPLEMENTED:character_card:sheet","TYPED_JSON_REBIND_NOT_IMPLEMENTED:dice_roll:data"),Set.copyOf(p.blockers()));}
    @Test void proposalBindsSeedArchiveCampaignAndNamespaceDeterministically(){UUID a=CampaignRemapPlan.proposal(seed,digest,source,target,"character_card",shared);assertNotEquals(shared,a);assertEquals(a,CampaignRemapPlan.proposal(seed,digest,source,target,"character_card",shared));assertNotEquals(a,CampaignRemapPlan.proposal(seed,digest,source,target,"dice_roll",shared));assertNotEquals(a,CampaignRemapPlan.proposal(seed,"b".repeat(64),source,target,"character_card",shared));assertNotEquals(a,CampaignRemapPlan.proposal(UUID.randomUUID(),digest,source,target,"character_card",shared));var reversed=new ArrayList<>(ids());Collections.reverse(reversed);assertEquals(plan(ids(),List.of(),Set.of(),tables()),plan(reversed,List.of(),Set.of(),tables()));}
    @Test void allExistingTypedUuidCollisionsBlockEvenInOtherNamespaces(){UUID collision=CampaignRemapPlan.proposal(seed,digest,source,target,"character_card",shared);var p=plan(ids(),List.of(),Set.of(collision,target),tables());assertTrue(p.blockers().contains("TARGET_ID_COLLISION"));assertTrue(p.blockers().contains("PROPOSED_ID_COLLISION:character_card"));}
    @Test void missingAndWrongNamespaceReferencesBlock(){var p=plan(ids(),List.of(new CampaignRemapPlan.Reference("token","character_id","character_card",UUID.randomUUID()),new CampaignRemapPlan.Reference("timeline_entry","action_id","combat_action",shared)),Set.of(),tables());assertTrue(p.blockers().contains("UNRESOLVED_REFERENCE:token:character_id"));assertTrue(p.blockers().contains("UNRESOLVED_REFERENCE:timeline_entry:action_id"));}
    @Test void badDuplicateIdentitiesAndSameTargetBlock(){var bad=new ArrayList<>(ids());bad.add(ids().get(1));bad.add(new CampaignRemapPlan.Identity("character_card",UUID.randomUUID(),-1L));var p=plan(bad,List.of(),Set.of(),tables());assertTrue(p.blockers().contains("DUPLICATE_IDENTITY:character_card"));assertTrue(p.blockers().contains("INVALID_VERSION:character_card"));assertTrue(CampaignRemapPlan.plan(source,source,seed,digest,ids(),List.of(),Set.of(),tables()).blockers().contains("SOURCE_TARGET_MUST_DIFFER"));}
    @Test void incompleteUnknownOrOccupiedUntypedCoverageBlocksAndReportsAreImmutable(){var data=new ArrayList<>(tables());data.removeFirst();data.add(new CampaignRemapPlan.Table("future_private","UNKNOWN",1,List.of(new CampaignRemapPlan.Column("payload","jsonb","TYPED_JSON_REBIND_REQUIRED",""))));var p=plan(ids(),List.of(),Set.of(),data);assertTrue(p.blockers().contains("TABLE_COVERAGE_MISMATCH"));assertTrue(p.blockers().contains("TYPED_JSON_REBIND_NOT_IMPLEMENTED:future_private:payload"));assertThrows(UnsupportedOperationException.class,()->p.mappings().clear());assertThrows(UnsupportedOperationException.class,()->p.tables().clear());assertThrows(UnsupportedOperationException.class,()->p.blockers().clear());}
    @Test void timelineIdentityMustShareItsCanonicalActivityTargetInsteadOfIndependentUuid(){var identities=new ArrayList<>(ids());identities.add(new CampaignRemapPlan.Identity("timeline_entry",shared,null));var alias=new CampaignRemapPlan.Alias(shared,"dice_roll",shared);var p=CampaignRemapPlan.plan(source,target,seed,digest,identities,List.of(),Set.of(),tables(identities),List.of(alias));var timeline=p.mappings().stream().filter(m->m.namespace().equals("timeline_entry")).findFirst().orElseThrow();var dice=p.mappings().stream().filter(m->m.namespace().equals("dice_roll")).findFirst().orElseThrow();assertEquals(dice.target(),timeline.target());assertEquals(List.of(alias),p.aliases());assertFalse(p.blockers().contains("PROPOSED_ID_COLLISION:timeline_entry"));assertTrue(p.blockers().stream().noneMatch(v->v.contains("COVERAGE_MISMATCH")));var invalid=new CampaignRemapPlan.Alias(shared,"character_card",shared);assertTrue(CampaignRemapPlan.plan(source,target,seed,digest,identities,List.of(),Set.of(),tables(identities),List.of(invalid)).blockers().contains("INVALID_TIMELINE_ALIAS"));}
    @Test void fakeScopeMissingIdentityAndWrongReferenceDeclarationAreNotAccepted(){var altered=new ArrayList<>(tables());var c=altered.stream().filter(t->t.name().equals("character_card")).findFirst().orElseThrow();altered.remove(c);altered.add(new CampaignRemapPlan.Table(c.name(),"GLOBAL_EXCLUDED",2,c.columns()));var p=plan(ids(),List.of(new CampaignRemapPlan.Reference("token","character_id","dice_roll",shared)),Set.of(),altered);assertTrue(p.blockers().contains("SCOPE_COVERAGE_MISMATCH:character_card"));assertTrue(p.blockers().contains("IDENTITY_COVERAGE_MISMATCH:character_card"));assertTrue(p.blockers().contains("REFERENCE_POLICY_MISMATCH:token:character_id"));}
}
